        introducedInEdition: "battletech-compendium", editionStats: { "battletech-compendium": { book: "BTC", page: 116, heat: 5, damagePerMissile: 1, range: { min: 6, short: 7, medium: 14, long: 21 }, weight: 8, criticals: 4, shotsPerTon: 8, cbills: 275000, errata: "The Inner Sphere table prints the Artemis IV FCS row one column to the right: nothing under Tonnage, 1 under Critical and 1 under Ammo. Entered as 1 ton and 1 critical slot, as the Clan table (BTC p.115) prints the same system.", notes: "The Artemis IV FCS is a table row of its own: 1 ton, 1 critical slot and 100,000 C-bills for each launcher, mounted in the launcher's location; the figures here are the launcher's plus the system's. Adds 2 on the Missile Hits table; every Artemis-compatible launcher on the unit must have one; its missiles cost double (BTC pp.118, 129)." }, "compendium-rules-of-warfare": { book: "BTC:RoW", page: 105, heat: 5, damagePerMissile: 1, range: { min: 6, short: 7, medium: 14, long: 21 }, weight: 8, criticals: 4, shotsPerTon: 8, cbills: 275000, notes: "The launcher's row plus the Artemis IV FCS row: 1 ton and 1 critical slot for each launcher, mounted in the launcher's location (a center torso launcher may use one in the head), and 100,000 C-bills (BTC:RoW p.124). Adds 2 to the Missile Hits Table roll; if any launcher of a class has it, every launcher of that class on the unit must. Not for Streak, Narc, Swarm or Thunder; may be used with one-shot packs. No effect on indirect LRM fire; nullified by an enemy Guardian ECM suite (BTC:RoW p.116). Its missiles cost twice as much (BTC:RoW pp.113-114)." }, "master-rules": { book: "BMR", page: 115, heat: 5, damagePerMissile: 1, range: { min: 6, short: 7, medium: 14, long: 21 }, weight: 8, criticals: 4, shotsPerTon: 8, cbills: 275000, notes: "The launcher's row plus the Artemis IV FCS row: 1 ton, 1 critical slot and 100,000 C-bills for each launcher, mounted in the launcher's location (a center torso launcher may use one in the head). Adds 2 to the Missile Hits Table roll; if any LRM (or SRM) launcher has it, every launcher of that class on the unit must. Not for Streak or Narc launchers or special munitions; may be used with single-shot launchers. No effect on indirect fire; blocked by an enemy ECM suite. Its missiles cost twice as much; with normal ammunition it works as a normal launcher (BMR p.123)." }, "master-rules-revised": { book: "BMR(R)", page: 121, heat: 5, damagePerMissile: 1, range: { min: 6, short: 7, medium: 14, long: 21 }, weight: 8, criticals: 4, shotsPerTon: 8, cbills: 275000, notes: "The launcher's row plus the Artemis IV FCS row: 1 ton, 1 critical slot and 100,000 C-bills for each launcher, mounted in the launcher's location (a center torso launcher may use one in the head). Adds 2 to the Missile Hits Table roll; if any LRM (or SRM) launcher has it, every launcher of that class on the unit must. Not for Streak or Narc launchers, nor for special munitions unless their rules allow it; may be used with single-shot launchers. No effect on indirect fire; blocked by an enemy ECM suite. Its missiles cost twice as much; with normal ammunition it works as a normal launcher. On a vehicle it is not a separate item (BMR(R) p.131)." } },
