const atmAmmoTypes = ["ammo-clan-atm-standard", "ammo-clan-atm-er", "ammo-clan-atm-he"];
const iatmAmmoTypes = [...atmAmmoTypes, "ammo-clan-iatm-inferno", "ammo-clan-iatm-mag-pulse"];

for (const equipment of equipmentMissile) {
    const atmMatch = equipment.tag.match(/^atm-(3|6|9|12)$/);
    const iatmMatch = equipment.tag.match(/^iatm-(3|6|9|12)$/);
    const launcherSize = Number(atmMatch?.[1] ?? iatmMatch?.[1]);

    if (launcherSize > 0) {
        equipment.ammoPerShot = launcherSize;
        equipment.ammoTypes = atmMatch ? atmAmmoTypes : iatmAmmoTypes;
    }
}
